def main():
    manifest,inputs=load_inputs(ROOT/'runs/AMD_baseline_1')
    spec={'protocol_version':'machine-adjudication-v1','run_id':manifest['run_id'],'evidence_run_id':manifest['run_id'],'raw_judge_audit':str(ROOT/'audits/grounding/AMD_before'),'sections':{}}
    for s,item in inputs.items():
        ids={u['unit_id'] for u in source_units(item['text'])}
        if set(D[s])!=ids:raise ValueError(f'Coverage mismatch {s}: {set(D[s]) ^ ids}')
        spec['sections'][s]={'source_sha256':item['metadata']['source_sha256'],'evidence_sha256':item['metadata']['evidence_prompt_sha256'],'units':[D[s][i] for i in sorted(ids)]}
    target=ROOT/'audits/grounding/AMD_before_reviewed_specification.json';target.write_text(json.dumps(spec,indent=2,ensure_ascii=False)+'\n',encoding='utf-8')
    print('Explicit source judgments saved:',sum(len(x['atoms']) for v in D.values() for x in v.values()),'atomic claims')
if __name__=='__main__':main()
